const serviceNames=['Hosting','Identity','Database','Private storage','Rate limiting','Background transport','Email','Monitoring','DNS','Independent backups','CI / scheduled jobs','Payments · future'];
const serviceImpact=[['Pages and API','الصفحات والواجهة'],['Sign-in and renewal','الدخول والتجديد'],['Membership and committed writes','العضويات والكتابات المحفوظة'],['Private uploads and downloads','الرفع والتنزيل الخاص'],['Protected-entry throttling','ضبط الدخول المحمي'],['Deferred business delivery','التسليم الخلفي'],['Invitations and transactional messages','الدعوات والرسائل التشغيلية'],['Detection and external alerts','الرصد والتنبيهات الخارجية'],['Domain reachability','الوصول إلى النطاق'],['Independent recovery copy','نسخة تعافٍ مستقلة'],['Verification and backup execution','الفحص وتنفيذ النسخ'],['Future payment settlement','تسوية مدفوعات مستقبلية']];
function serviceLabel(name){const i=serviceNames.indexOf(name);return q(name,['الاستضافة','الهوية','قاعدة البيانات','التخزين الخاص','ضبط المعدل','النقل الخلفي','البريد','المراقبة','نظام النطاقات','النسخ المستقلة','الفحوص والمهام المجدولة','المدفوعات · لاحقاً'][i]||name)}
function servicesPage(){const w=W(),index=Math.max(0,serviceNames.indexOf(w.service));const tabs=[['inventory','Service inventory','سجل الخدمات'],['health','Health & quality','الصحة والجودة'],['usage','Usage & limits','الاستخدام والحدود'],['costs','Costs & plans','التكاليف والخطط'],['impact','Capability impact','أثر الوظائف'],['backups','Backups & recovery','النسخ والتعافي'],['incidents','Incidents & changes','الحوادث والتغييرات']];let body='';if(w.serviceTab==='inventory')body=`<table class="data-table people-table"><thead><tr><th>${q('Service / environment','الخدمة والبيئة')}</th><th>${q('Observation','الملاحظة')}</th><th>${t('open')}</th></tr></thead><tbody>${serviceNames.map((s,i)=>`<tr><td><b>${esc(serviceLabel(s))}</b><div class="detail-secondary">LAB-OPS · ${q(...serviceImpact[i])}</div></td><td>${badge(q('Unknown · fictional inventory','غير معروف · سجل خيالي'),'warn')}</td><td>${btn(q('Inspect dependency','فحص الاعتماد'),'s-service:'+i,'small')}</td></tr>`).join('')}</tbody></table>`;else if(w.serviceTab==='health')body=property(q('Provider state','حالة المزود'),q('Unknown · no live provider probe','غير معروف · لا فحص حي'))+property(q('Collector state','حالة الجامع'),esc(stateLabel(w.collector)))+property(q('App workflow quality','جودة رحلة التطبيق'),q('Not measured; p75/p95, samples and failures required','غير مقاسة؛ يلزم المئينات والعينات والفشل'))+property(q('Source / last successful observation','المصدر وآخر ملاحظة ناجحة'),q('Fictional observation only; no current provider evidence','ملاحظة خيالية فقط؛ لا دليل مزود حالي'))+sButtons(btn(q('Simulate collector timeout','محاكاة انتهاء مهلة الجامع'),'s-collector-timeout'),btn(q('Restore collector fixture','استعادة نموذج الجامع'),'s-collector-recover'));else if(w.serviceTab==='usage')body=property(q('Meters and period','المقاييس والفترة'),q('Bytes / requests / connections as applicable; current values unknown','بايتات وطلبات واتصالات حسب الخدمة؛ القيم الحالية مجهولة'))+property(q('Allowance / reset / breach','السماح وإعادة الضبط والتجاوز'),q('Provider/version evidence required; no hardcoded cap','يلزم دليل المزود والإصدار؛ لا حد ثابت مفترض'))+property(q('Forecast','التوقع'),q('Unavailable: insufficient observation history','غير متاح: تاريخ ملاحظات غير كافٍ'));else if(w.serviceTab==='costs')body=property(q('Reported actual charge','التكلفة الفعلية المبلّغ عنها'),q('Unknown · invoice evidence not supplied','مجهولة · لم يُقدّم دليل فاتورة'))+property(q('Estimate / accrued usage','التقدير والاستخدام المستحق'),q('Unavailable; never substituted for an invoice','غير متاح؛ لا يحل محل الفاتورة'))+property(q('Currency / billing period','العملة وفترة الفوترة'),q('Source-specific · not selected','حسب المصدر · غير محددة'))+property(q('Trial / renewal / effective plan','التجربة والتجديد والخطة السارية'),q('Unverified fixture; scheduled change differs from effective state','مثال غير متحقق منه؛ المجدول مختلف عن الساري'))+property(q('Shared account allocation','توزيع الحساب المشترك'),q('Not attributed to AcademyOS without evidence','لا يُنسب إلى AcademyOS دون دليل'))+notice(q('No purchase action','لا إجراء شراء'),q('Budget warnings are not spending caps. No upgrade or subscription is executed.','تحذيرات الميزانية لا تحد الإنفاق. لا ترقية أو اشتراك منفذ.'));else if(w.serviceTab==='impact')body=property(q('Selected dependency','الاعتماد المختار'),esc(serviceLabel(w.service)))+property(q('Capability / users','الوظيفة والمستخدمون'),q(...serviceImpact[index]))+property(q('Trust boundary','حد الثقة'),q('Platform-only redacted observations; no tenant content access','ملاحظات منقّحة للمنصة فقط؛ لا وصول لمحتوى الأكاديمية'))+property(q('Fallback / recovery','البديل والتعافي'),q('Unknown until tested; preserve committed operations and deny unsafe writes','غير معروف حتى اختباره؛ حفظ العمليات ومنع الكتابات غير الآمنة'))+property(q('Environment / edge evidence','البيئة ودليل العلاقة'),'LAB-OPS · fictional-dependency-v1');else if(w.serviceTab==='backups')body=property(q('Latest independent copy','آخر نسخة مستقلة'),q('Fictional receipt SIM-COPY-1 · no real backup claim','إيصال خيالي SIM-COPY-1 · لا ادعاء نسخ فعلي'))+property(q('Latest actual restore','آخر استعادة فعلية'),q('Not performed in this design task','لم تُنفذ في مهمة التصميم'))+property(q('Coverage / exclusions','التغطية والاستثناءات'),q('DB and private objects require separate verified manifests','القاعدة والكائنات الخاصة تحتاج قوائم تحقق منفصلة'))+property(q('Retention / lock / RPO / RTO','الاحتفاظ والقفل وأهداف التعافي'),q('Production policy and measured recovery unresolved','سياسة الإنتاج والتعافي المقاس غير محسومين'))+notice(q('Restore proposal only','اقتراح استعادة فقط'),q('Exact target, snapshot, approval, isolation and independent verification must precede real restoration. No restore button is connected.','يلزم الهدف واللقطة والموافقة والعزل والتحقق المستقل قبل الاستعادة الفعلية. لا زر استعادة متصل.'));else body=btn(q('Open incident path','فتح مسار الحادث'),'nav:sIncident','primary')+property(q('Affected capability','الوظيفة المتأثرة'),q('Invitation delivery delayed · fictional incident','تأخر تسليم الدعوات · حادث خيالي'));
return sHead('sServices','S51–S58 · J27')+sPolicy('D-022 / operational-action policy',q('All provider observations are fictional or unknown. No account, token, collector or vendor API is contacted.','كل ملاحظات المزود خيالية أو مجهولة. لا اتصال بحساب أو رمز أو جامع أو واجهة مزود.'))+`<div class="filters">${tabs.map(([id,en,ar])=>`<button class="filter ${w.serviceTab===id?'active':''}" data-action="s-service-tab:${id}">${q(en,ar)}</button>`).join('')}</div><div class="work-card"><h2>${esc(serviceLabel(w.service))}</h2><p class="draft-note">${q('Platform Owner · LAB-OPS · observation age and source required','مالك المنصة · LAB-OPS · يلزم عمر الملاحظة ومصدرها')}</p>${body}</div>`}
function incidentPage(){const i=W().incident;return sHead('sIncident','S58/S56/S57 · J27-A01–A04')+`<div class="form-panel">${errorBox()}<div class="work-card">${property(q('Incident','الحادث'),'SIM-INC-1 · '+q('Invitation delivery delayed','تأخر تسليم الدعوات'))}${property(q('Impact','الأثر'),q('Pending owner invitations; existing academy access not inferred affected','دعوات المالك المعلّقة؛ لا يُفترض تأثر الوصول القائم'))}${property(q('Cause / confidence','السبب والثقة'),q('Investigation pending · provider outage and collector failure are distinct','التحقيق معلّق · تعطل المزود وفشل الجامع منفصلان'))}${property(t('status'),esc(stateLabel(i.state)))}${sField('incident-reason','Evidence / proposed bounded action','الدليل والإجراء المحدود المقترح')}${sConfirm('incident-review')}${sButtons(btn(q('Acknowledge & assign operator','الإقرار وتعيين مشغل'),'s-incident-ack'),btn(q('Record investigation evidence','تسجيل دليل التحقيق'),'s-incident-evidence'),btn(q('Prepare controlled action proposal','إعداد اقتراح إجراء مضبوط'),'s-incident-propose','primary'),btn(q('Advance fictional recovery observation','تقديم ملاحظة التعافي الخيالية'),'s-incident-recover'))}</div>${notice(q('Action boundary','حد الإجراء'),q('Proposal only: current authority, affected jobs, idempotency, approval and rollback/forward repair must be reviewed. No provider retry, credential rotation, restore or deletion is executed.','اقتراح فقط: تراجع السلطة والمهام وعدم التكرار والموافقة والتراجع أو الإصلاح. لا إعادة محاولة مزود أو تدوير مفتاح أو استعادة أو حذف.'))}</div>`}
function servicesAction(k,v){const w=W(),i=w.incident;if(k==='s-service'){w.service=serviceNames[+v]||serviceNames[0];w.serviceTab='impact';render();return true}if(k==='s-service-tab'){w.serviceTab=v;render();return true}if(k==='s-collector-timeout'||k==='s-collector-recover'){w.collector=k.endsWith('timeout')?'unavailable · last observation stale; provider state unknown':'fresh fixture · provider state still unknown';sSaved(sh('sServices'));return true}if(k.startsWith('s-incident-')){if(k==='s-incident-ack')i.state='acknowledged · demo operator';else if(k==='s-incident-evidence'){if(!sValue('incident-reason')){sError();return true}i.evidence=true;i.state='evidence recorded'}else if(k==='s-incident-propose'){if(!i.evidence||!sValue('incident-reason')||!sCheck('incident-review')){sError();return true}i.proposal=true;i.state='controlled proposal awaiting real approval'}else if(k==='s-incident-recover'){if(!i.proposal||!i.evidence||!sCheck('incident-review')){sError();return true}i.state='fictional recovery observed · independent verification pending'}sSaved(sh('sIncident'));return true}return false}
